        mm = re.search(r'"tool_use_id"\s*:\s*"([^"]+)"', raw)
        if mm and mm.group(1) in tu2agent:
            briefs[m.group(1)] = tu2agent[mm.group(1)]
import os
os.makedirs(dst + "/transcripts", exist_ok=True)
n = 0
for k, role in roles.items():
    if k in briefs:
        open(f"{dst}/transcripts/brief_{role}.md", "w", encoding="utf-8").write(briefs[k])
        n += 1
    if k in answers:
        open(f"{dst}/transcripts/answer_{role}.raw.txt", "w", encoding="utf-8").write(answers[k])
