        stat[f"brief:{role}"] = len(inp["prompt"])
    if k in answers:
        open(f"{dst}/transcripts/answer_{role}.raw.txt", "w", encoding="utf-8").write(answers[k])
        stat[f"answer:{role}"] = len(answers[k])
open(f"{dst}/usage_harness_raw.jsonl", "w", encoding="utf-8").write("\n".join(usage))
